 box.innerHTML=palHits.map((x,i)=>`<a href="${esc(x.h)}" data-i="${i}" class="${i===palSel?'sel':''}"${x.ext?' target="_blank" rel="noopener"':''}><span class="ty">${x.ty}</span><span class="tt">${esc(x.t)}${x.ext?' ↗':''}<span class="ds">${esc(x.d.slice(0,150))}</span></span></a>`).join('');
